  gV = `Ingen kategori`,
  _V = `Kanskje det var den fengslende spillopplevelsen, eller den gripende historien – de sterke karakterene, det fullkomne designet eller den vanedannende flerspilleren. Uansett årsak er vinneren av prisen som årets beste spill i 2020 allerede en klassiker.`,
  vV = `Årets VR-spill gjør mer enn å bare etterligne virkeligheten. Dette spillet forbedrer virkeligheten, drar nytte av VR-mediet og flytter grensene for den virtuelle verden.`,
  yV = `Dette spillet har vært ute en stund. Det er lenge siden teamet først avduket sin kreative baby, men som de gode foreldrene de er, fortsatte disse utviklerne å pleie og støtte sin skapelse. Dette spillet får, den dag i dag, fremdeles nytt innhold etter alle disse årene.`,
  bV = `Det er noen spill der ute som bare ikke er de samme når du spiller dem alene. Kanskje du trenger en venn du kan ha i ryggen. Kanskje du trenger å ha en venn du kan vende ryggen til. Uansett, så er det mye glede i vente for de som samler sammen venner og spiller dette spillet.`,
  xV = `Visuell stil handler ikke om å oppnå naturtro gjengivelse (som dog er et edelt mål i seg selv), men det beskriver et særegent utseende og preg som er gjennomført i hele spillet.`,
  SV = `Skaperne av dette spillet er fremtredende innen kreativ eksperimentering og bidrar med ferske perspektiver og forunderlige overraskelser. Spillet gledet, inspirerte og underholdte med en originalitet vi ikke har sett i spill før.`,
  CV = `Dette spillet belønner utholdenhet og er ikke for sarte sjeler. Det er det vanskeligste spillet vi noen gang har elsket.`,
  wV = `Denne ukjente helten fortjener anerkjennelse for den fantastiske musikken sin. Musikk som setter lydspor! `,
  TV = `Noen ganger er det bare et spill med en sterk fortelling som gjør susen, og dette spillet har både sus og dus! Det er like gripende som en såpeopera og med et manus som utkonkurrerer selv de beste TV-seriene. Bravissimo – det får oss virkelig til å føle noe!`,
  EV = `Dette er spillet du trenger på en travel dag. Det er rolig og avslappende, og får deg til å gi blaffen i bekymringer og strev. Så godt det er med en stund i ro og mak.`,
