  eU = `Del I av IV`,
  tU = `Del II av IV`,
  nU = `Del III av IV`,
  rU = `Del IV av IV`,
  iU = `Jadekeiseren kalte sammen alle dyrene i riket sitt til et kappløp til det himmelske palass, og erklærte at de tolv første i mål ville bli hedret med en plass i hans nye kalender.

Den smarte rotten var den første som krysset elven inn til det himmelske riket. Rotten var ikke så glad i å svømme, så den skaffet seg skyss på ryggen til den pålitelige oksen og hoppet begeistret over i keiserens hage like før begge nådde land.

Oksen krysset elven lekende lett. Den brydde seg ikke om resultatet av kappløpet, og var godt fornøyd med sin rolle i rottens suksess.`,
  aU = `Den selvstendige tigeren ferdes for forsiktig til å passere oksen, da den tenkte at det var bedre å komme frem på tredje enn ikke i det hele tatt.

Den kvikke haren hoppet på en tømmerstokk som skulle ingensteds. Men hell tjente haren bedre enn strategi, og en gunstig vind førte den improviserte båten av sted.

Den flyvende dragens gunstige utsikt avslørte en landsby i nød, så selvfølgelig gjorde dragen en stopp for å hjelpe – samtidig som den ga haren et vindpust i riktig retning. Ære var langt viktigere enn seier, og dragen syntes femteplassen passet fint.`,
  oU = `Den listige slangen var ikke spesielt interessert i et langdistanseløp, så den kveilet seg ubemerket rundt hestens forhov.

Da hesten nærmet seg målstreken i full galopp, kveilet slangen seg ut og skremte gangeren akkurat lenge nok til å smyge seg inn på sjetteplass – med den lettskremte hesten travende like bak.`,
  sU = `Geiten, apen og hanen jobbet sammen, men lot geiten ta åttendeplassen, da den var reisefølgets ryggrad. Den muntre apen var den neste, og den spradende hanen kom på en tiendeplass, stolt over at rekkefølgen var rettferdig.

Den lekne hunden var mest interessert i å plaske rundt og syntes at en ellevteplass var et godt bytte for all fornøyelsen.

Sist kom grisen, som hadde stoppet for en liten matbit og en lur – klok nok til å vite at hvert dyr skulle få sin del av keiserens gunst.`,
